"""Local test accounts are generated by the API, never hard-coded in tests."""
import json
import os
from pathlib import Path

import httpx

BASE = os.getenv("LMS_DATABASE_API", "http://localhost:8085")
ROOT = Path(__file__).resolve().parents[1]
SESSIONS = {}
ANONYMOUS = httpx.Client(trust_env=False, timeout=30)


def credentials():
    path = Path(os.getenv("LMS_TEST_CREDENTIALS", str(ROOT / ".local/initial-credentials.json")))
    return json.loads(path.read_text(encoding="utf-8-sig"))


def csrf(client):
    response = client.get(BASE + "/api/auth/csrf")
    response.raise_for_status()
    return {"X-CSRF-TOKEN": response.json()["token"]}


def login(username, password):
    client = httpx.Client(trust_env=False, timeout=30)
    response = client.post(BASE + "/api/auth/login", json={"username": username, "password": password}, headers=csrf(client))
    assert response.status_code == 200, response.text
    return client


def session(actor):
    if actor not in SESSIONS:
        SESSIONS[actor] = login(actor, credentials()[actor])
    return SESSIONS[actor]


def send(method, path, actor="admin", **kwargs):
    client = session(actor) if actor else ANONYMOUS
    headers = kwargs.pop("headers", {})
    if method.upper() not in ("GET", "HEAD", "OPTIONS"):
        headers.update(csrf(client))
    return client.request(method, path if path.startswith("http") else BASE + path, headers=headers, **kwargs)


def close_sessions():
    for client in SESSIONS.values():
        client.close()
    SESSIONS.clear()
